PRAGMA auto_vacuum=NONE; CREATE TABLE t1(a INTEGER PRIMARY KEY,b,c); WITH RECURSIVE x(n) AS (VALUES(1) UNION ALL SELECT n+1 FROM x WHERE n<256) INSERT INTO t1 SELECT n,printf('b%03d',n),printf('c%03d',n) FROM x; CREATE INDEX i1 ON t1(b,c); CREATE UNIQUE INDEX i2 ON t1(c,a); CREATE TABLE t2 AS SELECT * FROM t1; DROP TABLE t2;